import java.util.ArrayList;
import java.util.List;

class Solution {
    public ListNode reverseKGroup(ListNode head, int k) {
        List<ListNode> nodes = new ArrayList<>();
        for (ListNode current = head; current != null; current = current.next) nodes.add(current);
        for (int start = 0; start + k <= nodes.size(); start += k) {
            int left = start;
            int right = start + k - 1;
            while (left < right) {
                ListNode temporary = nodes.get(left);
                nodes.set(left++, nodes.get(right));
                nodes.set(right--, temporary);
            }
        }
        for (int index = 0; index + 1 < nodes.size(); index++) nodes.get(index).next = nodes.get(index + 1);
        if (nodes.isEmpty()) return null;
        nodes.get(nodes.size() - 1).next = null;
        return nodes.get(0);
    }
}

